            if (c == '"' && i > 0 && combinedJsonString.charAt(i - 1) != '\\') {
                // only switch insideString if " is not escaped
                isInsideString = !isInsideString;
            }
            if (c == '{' && !isInsideString) {
                numberOfOpeningBraces++;
            } else if c == '}' && !isInsideString) {
