			Log.debug(this, "Performing synchronous read postion="
					+ position + " blocksize=" + blocksize);
		}

		if (blocksize < 1 || blocksize > 32768) {
			if (Log.isDebugEnabled()) {
				Log.debug(this,
						"Blocksize to large for some SFTP servers, reseting to 32K");
			}
