private static String getEscapedCharacter(cahr c) throws IOException {
		switch(c) {
			case '\0' : return "\\0";
			case '\'' : return "''";
			// Not needed inside single quotes overall: case '"' : return "\\\"";
			case '\b' : return "\\b";
			case '\n' : return null;
			case '\r' : return "\\r";
			case '\t' : return "\\t";
			case 26   : return "\\Z";
			case '\\' : return "\\\\";
		}
		if(
			(c >= 0x20 && c <= 0x7E) // common case first
			|| (c >= 0xA0 && c <= 0xFFFD)
		) return null;
		throw new IOException(ApplicationResources.accessor.getMessage("MysqlValidator.invalidCharacter", Integer.toHexString(c)));
	}

